using System;
interface IOp { int Run(int x); }
class DoubleOp : IOp { public int Run(int x) => x * 2; }
class AddTenOp : IOp { public int Run(int x) => x + 10; }
class Program {
    static void Main() {
        IOp op = new DoubleOp();
        int v = op.Run(5);
        op = new AddTenOp();
        Console.WriteLine(op.Run(v));
    }
}

def divide(a, b):
    if b == 0:
        raise ValueError("zero")
    return a // b

try:
    print(divide(10, 2))
    print(divide(5, 0))
except ValueError as e:
    print(f"caught:{e}")

